N=30; g=[[0]*N for _ in range(N)]
# outer square is at rows/cols 1..25 (0-based). Every two cells inward, draw a 5 border; between successive borders, alternate 2 and 0. Final center pixel is 5.
for depth in range(0,13,2):
 lo,hi=1+depth,25-depth
 if lo>hi: break
 for j in range(lo,hi+1):
  g[lo][j]=g[hi][j]=5; g[j][lo]=g[j][hi]=5
 if depth<12 and hi-lo>=2:
  color=2 if (depth//2)%2==0 else 0
  for j in range(lo+1,hi):
   g[lo+1][j]=g[hi-1][j]=color
   g[j][lo+1]=g[j][hi-1]=color
print('\n'.join(' '.join(map(str,row)) for row in g))
